import re,math
from collections import defaultdict
lines=open('/workspace/text.gcode').read().splitlines()
x=y=z=0.0;e=0.0;abse=False;absxyz=True;obj=None
segs=defaultdict(list)
def pt(toks):
    d={}
    for t in toks:
        if t and t[0] in 'XYZEFIJK':
            try:d[t[0]]=float(t[1:])
            except:pass
    return d
for i,l in enumerate(lines,1):
    s=l.strip()
    if s.startswith('G90'):absxyz=True;continue
    if s.startswith('G91'):absxyz=False;continue
    if s.startswith('M82'):abse=False;continue
    if s.startswith('M83'):abse=True;continue
    if s.startswith('M486'):
        p=s.split()
        if len(p)>=2:
            if p[1]=='S-1':obj=None
            elif p[1][0]=='S':
                try:obj=int(p[1][1:])
                except:pass
        continue
    m=re.match(r'^(G[0-3])\b(.*)$',s)
    if not m:continue
    cmd=m.group(1);d=pt(m.group(2).split())
    nx,ny,nz,ne=x,y,z,e
    if 'X' in d:nx=d['X'] if absxyz else x+d['X']
    if 'Y' in d:ny=d['Y'] if absxyz else y+d['Y']
    if 'Z' in d:nz=d['Z'] if absxyz else z+d['Z']
    if 'E' in d:ne=d['E'] if abse else e+d['E']
    de=ne-e
    if de>1e-9 and ('X' in d or 'Y' in d):
        if cmd in ('G1','G0'): segs[(obj,round(z,3))].append((x,y,nx,ny,de))
        else:
            cx=x+d.get('I',0);cy=y+d.get('J',0);r=math.hypot(x-cx,y-cy)
            a0=math.atan2(y-cy,x-cx);a1=math.atan2(ny-cy,nx-cx)
            if cmd=='G3':
                while a1<=a0:a1+=2*math.pi
            else:
                while a1>=a0:a1-=2*math.pi
            n=max(2,int(abs(a1-a0)*r/0.25));px,py=x,y
            for k in range(1,n+1):
                a=a0+(a1-a0)*k/n;qx=cx+r*math.cos(a);qy=cy+r*math.sin(a)
                segs[(obj,round(z,3))].append((px,py,qx,qy,de/n));px,py=qx,qy
    x,y,z,e=nx,ny,nz,ne
def render(key,W=100,H=42,ch='#'):
    ss=segs.get(key)
    xs=[v for s in ss for v in (s[0],s[2])]; ys=[v for s in ss for v in (s[1],s[3])]
    x0,x1=min(xs),max(xs);y0,y1=min(ys),max(ys)
    grid=[[' ']*W for _ in range(H)]
    for a,b,c,d,de in ss:
        n=max(2,int(max(abs(c-a),abs(d-b))/0.05))
        for k in range(n+1):
            t=k/n;gx=int((a+(c-a)*t-x0)/(x1-x0)*(W-1));gy=int((y1-(b+(d-b)*t))/(y1-y0)*(H-1))
            if 0<=gx<W and 0<=gy<H:grid[gy][gx]=ch
    return '\n'.join(''.join(r) for r in grid)
for z in [20.08]:
    print('z',z)
    print(render((0,z)))
print('--- z 0.48 raw segments ---')
for s in segs[(0,0.48)]: print(s)
