from PIL import Image
import numpy as np
# braille dot bit map
bits={(0,0):1,(0,1):2,(0,2):4,(0,3):64,(1,0):8,(1,1):16,(1,2):32,(1,3):128}
def braille(arr):
    H,W=arr.shape
    rows=[]
    for by in range(0,H,4):
        line=[]
        for bx in range(0,W,2):
            code=0
            for dx in range(2):
                for dy in range(4):
                    x=bx+dx;y=by+dy
                    if x<W and y<H and arr[y,x]>0:
                        code|=bits[(dx,dy)]
            line.append(chr(0x2800+code) if code else ' ')
        rows.append(''.join(line).rstrip())
    return rows
