import urllib.request,lzma,re,os,sys,subprocess
BASE='http://deb.debian.org/debian/'
IDX='/workspace/Packages.xz'
if not os.path.exists(IDX):
    urllib.request.urlretrieve(BASE+'dists/bookworm/main/binary-amd64/Packages.xz',IDX)
txt=lzma.open(IDX,'rt',encoding='utf-8',errors='replace').read()
pkgs={}
for blk in txt.split('\n\n'):
    m=re.search(r'^Package: (.+)$',blk,re.M)
    if not m: continue
    name=m.group(1)
    fn=re.search(r'^Filename: (.+)$',blk,re.M)
    if fn: pkgs.setdefault(name,fn.group(1))
# installed set from dpkg status
inst=set()
try:
    st=open('/var/lib/dpkg/status',encoding='utf-8',errors='replace').read()
    for blk in st.split('\n\n'):
        m=re.search(r'^Package: (.+)$',blk,re.M)
        s=re.search(r'^Status: (.+)$',blk,re.M)
        if m and s and 'install ok installed' in s.group(1): inst.add(m.group(1))
except Exception as e: print('status err',e)
os.makedirs('/workspace/sysroot/debs',exist_ok=True)
os.makedirs('/workspace/sysroot/root',exist_ok=True)
want=sys.argv[1:]
got=0
for name in want:
    if name in inst:
        print('installed-skip',name); continue
    fn=pkgs.get(name)
    if not fn:
        print('NOTFOUND',name); continue
    out='/workspace/sysroot/debs/'+fn.split('/')[-1]
    if not os.path.exists(out):
        urllib.request.urlretrieve(BASE+fn,out)
    subprocess.run(['dpkg-deb','-x',out,'/workspace/sysroot/root'],check=False)
    print('ok',name,fn.split('/')[-1]);got+=1
print('fetched',got)
